param([ValidateSet('build','test')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-wmma-dot-chain-20260916';$seed='D:\projects\AIMA-public-dyadic-scan-qk-20260916';$sha='cc995ed8836b7fa0d656613b4bc79e3fff98e2aa';$bundle='D:\projects\wmma-dot-chain-cc995ed.bundle'
function Verify-File([string]$Path,[string]$Hash){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Hash){throw ('Changed input: '+$Path)}}
Verify-File $bundle '17584113b1d54505d89a1762abcb01cb8d2828eeaf83b6708e83e1b9a6b43580'
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\wmma-dot-chain';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\wmma_dot_chain_probe.cpp';$exe=Join-Path $build 'wmma-dot-chain.exe';$provenance=Join-Path $build 'build-provenance.json'
$sourceInputs=@(@($source,(Join-Path $repo 'tests\native\wmma_integer_rounding_probe.cpp'))|ForEach-Object {@{file=$_;sha256=(Get-FileHash $_ -Algorithm SHA256).Hash.ToLowerInvariant()}})
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; isolated exactly representable integer inputs';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;product_dispatch_changed=$false;purpose='Compare native zero-C BF16 and FP16 WMMA with seven FP16 DOT2 pair/accumulation orders and an explicit scalar-FMA control. The two operand encodings represent identical bounded integers. Repeat every native result, compare with the independent int64 oracle, verify immutable operands and redzones, and save every output word for arithmetic analysis. This is a generated hardware diagnostic without a model, provider change or performance acceptance.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=150
}else{
 $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha){throw 'Build commit mismatch'}
 Verify-File $exe $meta.executable.sha256
 foreach($file in $meta.source_inputs){Verify-File $file.file $file.sha256}
 $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant()
 $capture=Join-Path $build 'capture';if(Test-Path $capture){throw 'Capture already exists'};$null=New-Item -ItemType Directory -Path $capture
 $spec.executable=$exe;$spec.arguments=@($capture);$spec.output_directory=$capture;$timeout=120
}
$out=Join-Path $repo ('build\wmma-dot-chain-'+$Action+'-r1');$specPath=Join-Path $build ($Action+'-spec-r1.json')
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Evidence already exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 8|ForEach-Object {$_.Substring(0,[Math]::Min(2000,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native diagnostic action failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $diagnostics=@($reports|Where-Object {$_.kind -eq 'wmma_dot_chain_diagnostic'})
 $inputs=@($reports|Where-Object {$_.kind -eq 'wmma_dot_chain_inputs'})
 if($diagnostics.Count -ne 128 -or $inputs.Count -ne 2){throw 'Incomplete chain diagnostic'}
 foreach($r in $diagnostics){if(-not $r.redzones_pass -or -not $r.repeat_bit_parity -or ($r.variant -eq 6 -and $r.exact_integer_mismatches -ne 0)){throw 'Chain validation failed'}}
 foreach($r in $inputs){if(-not $r.immutable_inputs -or -not $r.redzones_pass){throw 'Input or guard changed'}}
 $files=@(Get-ChildItem -LiteralPath $capture -Filter '*.bin' -File|Sort-Object Name|ForEach-Object {@{name=$_.Name;bytes=$_.Length;sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}})
 if($files.Count -ne 18){throw 'Incomplete raw outputs'}
 [IO.File]::WriteAllText((Join-Path $build 'capture-manifest.json'),($files|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
}

